// Package machineauth implements ADR-0021 machine identities: tenant-local
// OAuth2 client_credentials service accounts that replace long-lived
// username/password credentials for automation and third-party integrations.
//
// A service account has one stable public client_id, a human-facing name,
// a fixed set of ADR-0022 permission-point scopes and one or two secret
// rows. Secrets are stored only as argon2id hashes (identity.HashSecret);
// the plaintext is generated by the server and returned exactly once at
// creation and rotation. Two concurrent secrets support overlap rotation:
// the old PRIMARY is demoted to ROTATING, kept until the next rotation.
//
// The package performs authentication and scope issuance only. Permission
// enforcement stays in internal/rbac: an issued token carries its scopes
// as JWT claims and the RBAC resolver builds a machine principal from
// them.
package machineauth

import (
	"errors"
	"strings"
	"time"

	"github.com/nereidai/nereidlink/internal/rbac"
)

// Sentinel errors map to distinct REST responses so an operator can tell
// a disabled account from a wrong secret without the endpoint leaking
// which half of the credential pair was wrong.
var (
	// ErrInvalidArgument is a malformed service-account request.
	ErrInvalidArgument = errors.New("invalid service account argument")

	// ErrNotFound is an unknown client_id or account id.
	ErrNotFound = errors.New("service account not found")

	// ErrConflict is a duplicate client_id or name.
	ErrConflict = errors.New("service account conflict")

	// ErrDisabled is an enabled=false authentication attempt.
	ErrDisabled = errors.New("service account is disabled")

	// ErrInvalidCredentials is a wrong or expired secret. Unknown client
	// and wrong secret share it to prevent client_id enumeration.
	ErrInvalidCredentials = errors.New("invalid client credentials")

	// ErrLocked is a credential endpoint under temporary failure lockout.
	ErrLocked = errors.New("client credentials temporarily locked")
)

// Secret labels stored in service_account_secret.label.
const (
	// LabelPrimary is the current secret.
	LabelPrimary = "PRIMARY"
	// LabelRotating is the previous secret kept for overlap deployment.
	LabelRotating = "ROTATING"
)

// ServiceAccount is the management view of a machine identity. It never
// contains any secret material: secret_hash is not part of this type.
type ServiceAccount struct {
	// ID is the internal account UUID.
	ID string `json:"id"`

	// TenantID is the owning tenant; machine accounts are tenant-local.
	TenantID string `json:"tenant_id"`

	// ClientID is the public OAuth2 client identifier.
	ClientID string `json:"client_id"`

	// Name is the operator-facing description of the integration.
	Name string `json:"name"`

	// Scopes are the permission points a token from this account may
	// exercise in its tenant.
	Scopes []string `json:"scopes"`

	// Enabled switches authentication without deleting the account.
	Enabled bool `json:"enabled"`

	// LastUsedAt is the last successful token grant as RFC3339 UTC,
	// empty before first use.
	LastUsedAt string `json:"last_used_at,omitempty"`

	// CreatedAt is RFC3339 UTC.
	CreatedAt string `json:"created_at"`

	// UpdatedAt is RFC3339 UTC.
	UpdatedAt string `json:"updated_at"`
}

// CreateInput carries the fields for a new service account.
type CreateInput struct {
	// Name is required and operator-facing.
	Name string

	// Scopes defaults to empty, which yields a token that authenticates
	// but is authorized for nothing; callers are expected to request at
	// least one point. '*' grants every tenant point.
	Scopes []string

	// SecretExpiresAt optionally bounds the issued secret; nil means no
	// expiry (rotation is then a manual operation).
	SecretExpiresAt *time.Time
}

// Credentials is returned exactly once by Create and RotateSecret. The
// ClientSecret cannot be retrieved afterwards because only its hash is
// stored.
type Credentials struct {
	// ClientID is the stable public identifier.
	ClientID string `json:"client_id"`

	// ClientSecret is the plaintext secret, available only in this
	// response.
	ClientSecret string `json:"client_secret"`
}

// CreateResult is the outcome of account creation.
type CreateResult struct {
	// Account is the stored management record.
	Account ServiceAccount

	// Credentials are the one-time plaintext credentials.
	Credentials Credentials
}

// RotateResult is the outcome of a secret rotation.
type RotateResult struct {
	// Account is the updated management record.
	Account ServiceAccount

	// ClientID is the stable identifier the new secret belongs to.
	ClientID string

	// NewSecret is the plaintext replacement secret, available once.
	NewSecret string

	// RotatingExpiresAt is the expiry of the demoted old secret, or
	// empty when the old secret had no expiry. It is returned so an
	// operator knows how long overlap deployment may take.
	RotatingExpiresAt string
}

// NormalizeScopes trims, de-duplicates and validates a requested scope
// list against the machine-grantable subset of the RBAC point catalog.
// An empty list is valid (a token with no rights) but every non-empty
// value must be grantable, so the database and the API can never
// disagree. Identity-administration points are rejected here even though
// the CHECK constraint knows them: an automation identity must not be
// able to mint another automation identity.
func NormalizeScopes(requested []string) ([]string, error) {
	seen := map[string]bool{}
	out := make([]string, 0, len(requested))
	for _, raw := range requested {
		scope := strings.TrimSpace(raw)
		if scope == "" {
			continue
		}
		if !rbac.IsMachineGrantable(scope) {
			return nil, errors.New("scope is not grantable to a service account: " + scope)
		}
		if !seen[scope] {
			seen[scope] = true
			out = append(out, scope)
		}
	}
	return out, nil
}
